/**
 * ModBot — Fichier de traductions
 * ═══════════════════════════════════════════════════════════════════
 *
 * POUR MODIFIER UN TEXTE : trouve sa clef et change la valeur. C'est tout.
 * POUR AJOUTER UNE LANGUE : copie tout le bloc « fr », renomme-le avec le
 * code de la langue, traduis les valeurs, puis ajoute l'option dans les
 * balises <select id="siteLanguage"> des pages HTML.
 *
 * Dans le HTML, un texte traduit porte un attribut :
 *   <p data-i18n="hero.lead">Texte par defaut</p>
 *   <input data-i18n-placeholder="search.placeholder">
 *   <button data-i18n-title="nav.close">
 *   <span data-i18n-aria="menu.label">
 *
 * Si une clef manque dans une langue, le francais sert de repli : rien ne
 * casse, le texte reste simplement en francais.
 *
 * Ce fichier doit etre charge AVANT script.js.
 */

