    "wiki.administration": "Administration",
    "wiki.quoiSertModbot": "À quoi sert ModBot ?",
    "wiki.modbotSertProtegerUne": "ModBot sert à protéger une communauté Discord avec des outils simples : sécurité, modération, logs, salons configurables, tickets, ratings, annonces, messages récurrents, rôles réactions et automatisations utiles au staff.",
    "wiki.securite": "Sécurité",
    "wiki.antiLienAntiSpam": "Anti-lien, anti-spam, anti-raid, alertes staff et lockdown propre.",
    "wiki.moderation": "Modération",
    "wiki.sanctionsAvertissementsLogsClear": "Sanctions, avertissements, logs, clear messages et suivi des actions.",
    "wiki.support": "Support",
    "wiki.ticketsConfigurablesPrioritesTranscripts": "Tickets configurables, priorités, transcripts, ratings et support staff.",
    "wiki.parQuiEtPourquoi": "Par qui et pourquoi ?",
    "wiki.modbotEstPensePour": "ModBot est pensé pour les serveurs qui veulent garder une communauté propre, claire et bien organisée sans devoir multiplier les bots. L’objectif est d’avoir un outil central, compréhensible par les admins, et agréable pour les membres.",
    "wiki.offresDisponibles": "Offres disponibles",
    "wiki.gratuit": "Gratuit",
    "wiki.toutesLesFonctionnalitesSur": "Toutes les fonctionnalités, sur tous les serveurs, sans limite de durée : sécurité, modération, logs, sauvegardes, tickets, ratings et réseaux.",
    "wiki.dons": "Dons",
    "wiki.leProjetVitDe": "Le projet vit de dons libres via PayPal. Un don ne débloque rien : tout est déjà accessible.",
    "wiki.modulesDuDashboard": "Modules du dashboard",
    "wiki.dashboardTreizeSections": "Le dashboard compte quatorze sections, regroupées par thème dans le menu de gauche. Sur téléphone, ce menu devient une liste déroulante qui affiche les quatorze entrées avec leurs intitulés de groupe.",
    "wiki.vueGlobaleEtatDu": "Vue globale : état du serveur, membres, sanctions récentes et raccourcis.",
    "wiki.securiteProtectionsAntiSpam": "Sécurité : anti-spam, anti-lien, anti-raid, anti-nuke, captcha et alertes staff.",
    "wiki.moderationSanctions": "Modération : sanctions, avertissements, seuils automatiques et immunités.",
    "wiki.rechercheMembresRoles": "Recherche : retrouver un membre ou un rôle, et agir dessus sans quitter la page.",
    "wiki.sauvegardesRestauration": "Sauvegardes : copie des salons et rôles, puis restauration additive.",
    "wiki.logsHistorique": "Logs : historique des actions du bot et du staff, filtrable.",
    "wiki.ticketsMessagePublicOptions": "Tickets : message public, options, emojis, salon, rôle support et publication.",
    "wiki.bienvenueModule": "Bienvenue : messages d’arrivée et de départ, message privé et carte illustrée.",
    "wiki.giveawaysModule": "Giveaways : création, durée, nombre de gagnants, relance et tirage.",
    "wiki.ratingsModule": "Ratings : notes laissées par les membres après un ticket.",
    "wiki.salonsIdsDesSalons": "Salons : salons utilisés par les systèmes du bot.",
    "wiki.reseauxRelaisAutomatiqueTwitter": "Réseaux : relais automatique Twitter/X, TikTok, Twitch et Instagram.",
    "wiki.langueModule": "Langue : langue des messages du bot et pays du serveur.",
    "wiki.verificationTitre": "Vérification à l’arrivée",
    "wiki.verificationTexte": "Le captcha demande au nouveau membre de recopier un code affiché en image. Les lettres occupent la majeure partie de l’image : elles se lisent sur un téléphone sans zoomer, tout en restant déformées pour gêner un robot.",
    "wiki.captchaRole": "Code validé, le membre reçoit automatiquement le rôle <strong>Verifier</strong> — ou celui que tu as choisi dans la section Sécurité.",
    "wiki.captchaRoleCree": "Si le rôle n’existe pas encore, le bot le crée au premier usage : rien à préparer à la main.",
    "wiki.captchaDelai": "Un délai d’expulsion facultatif écarte ceux qui ne se vérifient jamais.",
    "wiki.bienvenueTitre": "Arrivées et départs",
    "wiki.bienvenueTexte": "À chaque arrivée et à chaque départ, ModBot publie une carte : l’avatar du membre en rond, la phrase d’accueil et son numéro d’inscription. Le texte s’adapte à la longueur du pseudo au lieu d’être coupé.",
    "wiki.bienvenueImage": "L’image de fond se choisit depuis la galerie du téléphone ou l’explorateur de l’ordinateur : aucune URL à coller. Elle est réduite automatiquement.",
    "wiki.bienvenueSalons": "Salon d’arrivée et salon de départ sont deux réglages distincts. Laissé vide, le salon de départ reprend celui des arrivées — jamais l’inverse : un message de bienvenue ne part jamais dans le salon des départs.",
    "wiki.bienvenueMp": "Un message privé facultatif accueille le membre directement.",
    "wiki.bienvenueVariables": "Les variables <code>{user}</code>, <code>{server}</code> et <code>{memberCount}</code> sont remplacées à l’envoi.",
    "wiki.compteTitre": "Compte Discord et langue",
    "wiki.compteTexte": "La pastille en haut du dashboard indique avec quel compte Discord tu es connecté. Son menu permet de changer de compte sans fermer la page — utile quand on gère des serveurs depuis deux comptes différents — ou de se déconnecter.",
    "wiki.compteChangement": "« Changer de compte » prévient le bot, efface la session locale, puis rouvre l’écran de connexion Discord avec le sélecteur de comptes.",
    "wiki.langueSite": "Le site et le dashboard existent en français, anglais et arabe. Le choix est retenu d’une visite à l’autre.",
    "wiki.languePays": "La section Langue règle aussi la langue des messages du bot et le pays du serveur, affiché sur la carte publique de l’accueil.",
    "wiki.commandesPrincipales": "Commandes principales",
    "wiki.ouvreLePanneauAdministration": "Ouvre le panneau d’administration Discord.",
    "wiki.afficheLeRecapitulatifDes": "Affiche le récapitulatif des commandes et le lien du site.",
    "wiki.supprimeEntreEtMessages": "Supprime entre 1 et 100 messages dans le salon courant.",
    "wiki.nettoieLesMessagesDu": "Nettoie les messages du salon selon les limites Discord.",
    "wiki.traduitUnMessageVia": "Traduit un message via réponse ou ID de message.",
    "wiki.envoieUneSuggestionAu": "Envoie une suggestion au salon configuré.",
    "wiki.publieDesPatchNotes": "Publie des patch notes dans le salon où la commande est faite.",
    "wiki.publieUneAnnonceDans": "Publie une annonce dans le salon choisi par ID.",
