    "wiki.systemeDeTickets": "Système de tickets",
    "wiki.leMessageDeTicket": "Le message de ticket se publie depuis le dashboard. Le staff peut choisir la priorité du ticket dans l’interface Discord : P1, P2 ou P3. La couleur est ajoutée devant le nom du salon. Les transcripts doivent être envoyés en MP et les ratings sont centralisés dans le panel.",
    "wiki.administrationDuSite": "Administration du site",
    "wiki.espaceAdministrateurEstSepare": "L’espace administrateur est séparé du dashboard serveur. Il sert à gérer les accès admin, la blacklist des membres du bot, les serveurs détectés et les logs globaux d’utilisation.",

    // ── Politique de confidentialite ──────────────────────────────
    "priv.navigation": "Navigation ModBot",
    "priv.accueilModbot": "Accueil ModBot",
