    "roles.intro": "Two ways to hand out a role without anyone lifting a finger. <strong>On arrival</strong>: the role lands by itself when someone joins. <strong>By reaction</strong>: members pick for themselves, from a panel. Both are written to the audit log, under <strong>Roles</strong>.",
