    "welcome.channelsHelp": "Arrivals and departures can go to two different channels. Left empty, the leave channel falls back to the join channel — never the other way round.",
    "wiki.journalRoles": "The “Roles” category also records roles taken or returned by reaction, and auto-roles granted on arrival — with the reason whenever one fails.",
