    "wiki.reseauxMessage": "Each relay carries its own announcement text, for example <code>{account} is live, come and watch!</code>. It goes out with the mention, inside the message.",
    "wiki.reseauxSommaire": "Socials",
    "wiki.reseauxVariables": "Four variables: <code>{account}</code> the account being followed, <code>{platform}</code> the network, <code>{title}</code> the post title and <code>{link}</code> its direct link.",
