    "wiki.leMessageDeTicket": "تُنشر رسالة التذاكر من لوحة التحكم. يمكن للفريق اختيار أولوية التذكرة من واجهة ديسكورد: P1 أو P2 أو P3. يُضاف اللون قبل اسم القناة. تُرسل نسخ المحادثات في رسالة خاصة وتُجمع التقييمات في اللوحة.",
    "wiki.administrationDuSite": "إدارة الموقع",
    "wiki.espaceAdministrateurEstSepare": "مساحة الإدارة منفصلة عن لوحة تحكم الخادم. تُستخدم لإدارة صلاحيات المشرفين والقائمة السوداء لأعضاء البوت والخوادم المكتشَفة وسجلات الاستخدام العامة.",

