    "priv.resumeTitre": "باختصار",
    "priv.resume1": "يعالج ModBot معرّفات ديسكورد (المعرّف والاسم والصورة) وسجل العقوبات، لأن أداة إشراف لا يمكن أن تعمل بدونها.",
    "priv.resume2": "يُقرأ محتوى الرسائل <strong>لحظيًا</strong> بواسطة الإشراف التلقائي، لكنه <strong>لا يُحفظ</strong> لدى البوت.",
    "priv.resume3": "لا قياس لزيارات الموقع: لا ملفات تعريف إعلانية، ولا متتبّعات، ولا عدّاد زيارات.",
    "priv.resume4": "لا شيء يُباع أو يُؤجَّر أو يُنقل إلى أطراف ثالثة خارج مزوّدي الخدمات التقنية المذكورين أدناه.",
    "priv.resume5": "إزالة ModBot من الخادم تكفي لإيقاف كل معالجة؛ أما حذف البيانات المخزّنة فيُطلب عبر جهة الاتصال المذكورة.",
    "priv.responsableTitre": "من يعالج البيانات",
    "priv.responsableTexte": "ModBot مشروع شخصي ومجاني. المسؤول عن المعالجة هو مالك البوت، ويمكن الوصول إليه عبر خادم الدعم على ديسكورد المرتبط أعلى هذه الصفحة. لا تدير هذه الخدمة أي شركة.",
    "priv.responsableServeur": "في كل خادم، يقرّر المسؤول الذي يثبّت ModBot ما يُفعَّل: قنوات السجلات، والإشراف التلقائي، والكابتشا، ورسائل الترحيب. وهو من يختار ما يراقبه البوت في خادمه.",
    "priv.donneesTitre": "البيانات المعالَجة، ولماذا",
    "priv.thDonnee": "البيانات",
    "priv.thPourquoi": "السبب",
    "priv.thOu": "المكان",
    "priv.d1": "معرّف ديسكورد والاسم والصورة",
