    "priv.d3": "سجل إجراءات لوحة التحكم",
    "priv.p3": "معرفة من غيّر أي إعداد، ومتى",
    "priv.o3": "قاعدة بيانات البوت",
    "priv.d4": "جلسة لوحة التحكم: رمز ديسكورد والمعرّف والاسم والصورة وقائمة الخوادم المُدارة",
    "priv.p4": "التعرّف عليك من صفحة إلى أخرى والتحقق من صلاحياتك في كل خادم",
    "priv.o4": "قاعدة بيانات البوت",
    "priv.d5": "إعدادات الخادم: القنوات والرتب والنصوص وصورة بطاقة الترحيب",
    "priv.p5": "تشغيل البوت وفق ما أعدّه المسؤول",
    "priv.o5": "قاعدة بيانات البوت",
    "priv.d6": "كابتشا قيد الانتظار: الرمز ومعرّف العضو",
    "priv.p6": "التحقق من الإجابة عند الدخول",
    "priv.o6": "قاعدة بيانات البوت",
    "priv.d7": "محتوى الرسائل",
    "priv.p7": "الإشراف التلقائي: الروابط والشتائم والسبام. يُقرأ لحظيًا ولا يُسجَّل",
    "priv.o7": "في الذاكرة فقط",
    "priv.d8": "لغة الخادم وبلده",
    "priv.p8": "لغة رسائل البوت، والخريطة العامة للخوادم المحمية",
    "priv.o8": "قاعدة بيانات البوت",
    "priv.donneesNote": "ملاحظتان مفيدتان. عندما يحذف الإشراف التلقائي رسالة، يُعاد نشر مقتطف منها في قناة السجلات التي اختارها المسؤول: يعيش هذا المقتطف عندئذٍ على ديسكورد داخل الخادم، لا لدى ModBot. أما نص التذكرة فيُنتَج عند الطلب ويُرسل في رسالة خاصة؛ ولا يؤرشفه البوت.",
    "priv.jamaisTitre": "ما لا يفعله ModBot",
    "priv.jamais1": "لا بيع ولا تأجير ولا مشاركة للبيانات، مع أي جهة.",
    "priv.jamais2": "لا إعلانات ولا تصنيف إعلاني.",
    "priv.jamais3": "لا قياس لزيارات الموقع: الزيارات غير محسوبة، ومساحة الإدارة تصرّح بذلك.",
    "priv.jamais4": "لا ملفات تتبّع. يحتفظ الموقع في متصفحك بلغتك وجلسة لوحة التحكم فقط.",
    "priv.jamais5": "لا قراءة لرسائلك الخاصة على ديسكورد.",
    "priv.jamais6": "لا أرشفة لمحادثات الخوادم.",
    "priv.dureeTitre": "لكم من الوقت",
    "priv.duree1": "<strong>جلسة لوحة التحكم</strong>: سبعة أيام كحد أقصى، وتُمحى فورًا عند تسجيل الخروج أو تبديل الحساب.",
    "priv.duree2": "<strong>كابتشا قيد الانتظار</strong>: حتى التحقق منها أو انتهاء صلاحيتها.",
    "priv.duree3": "<strong>محتوى الرسائل</strong>: مدة الفحص فقط، ولا يُكتب شيء على القرص.",
    "priv.duree4": "<strong>العقوبات والإعدادات والسجل</strong>: تُحفظ ما دام ModBot موجودًا في الخادم، فهذه غايتها. ويمكن محوها عند الطلب.",
    "priv.destTitre": "إلى من تُنقل البيانات",
    "priv.destTexte": "يعتمد ModBot على عدد قليل من مزوّدي الخدمات التقنية. ولا توجد أي جهة متلقّية أخرى.",
    "priv.thQui": "المزوّد",
    "priv.thQuoi": "ما يتلقاه",
    "priv.thQuand": "متى",
    "priv.dest1": "كل ما يمر عبر المنصة: فهي التي تستضيف الخوادم والحسابات",
    "priv.destQuand1": "باستمرار",
    "priv.dest2": "يستضيف البوت وواجهته البرمجية، وبالتالي القاعدة الموصوفة أعلاه",
    "priv.destQuand2": "باستمرار",
    "priv.dest3": "يستضيف الموقع ولوحة التحكم، دون قاعدة بيانات",
    "priv.destQuand3": "باستمرار",
    "priv.dest4": "السؤال المطروح، والتبادلات الأخيرة في المحادثة، واسم صاحبها",
    "priv.destQuand4": "فقط عندما يخاطب أحدهم المساعد الذكي",
    "priv.dest5nom": "ترجمة جوجل، ثم MyMemory كبديل",
    "priv.dest5": "النص المراد ترجمته، لا غير",
    "priv.destQuand5": "فقط عند استخدام أمر الترجمة",
    "priv.destNote": "بعبارة أخرى: بدون المساعد الذكي وبدون أمر الترجمة، لا يخرج شيء عن ديسكورد وRailway وVercel.",
    "priv.baseTitre": "على أي أساس",
    "priv.baseTexte": "تستند المعالجة إلى المصلحة المشروعة لمسؤول الخادم في الإشراف على مجتمعه، وإلى تنفيذ الخدمة التي تطلبها عند استخدام لوحة التحكم. فإضافة ModBot إلى خادم قرارٌ يتخذه مسؤوله؛ واستخدام لوحة التحكم تسجيل دخول طوعي منك.",
    "priv.droitsTitre": "حقوقك",
    "priv.droitsTexte": "يمكنك طلب الاطلاع على البيانات المتعلقة بك، أو تصحيحها، أو محوها. ويُقدَّم الطلب في خادم الدعم على ديسكورد من الحساب المعني — وهو ما يتيح التحقق من أنك أنت بالفعل.",
    "priv.droit1": "<strong>الاطلاع</strong>: تُرسل إليك قائمة بما هو مسجَّل عنك.",
    "priv.droit2": "<strong>المحو</strong>: تُحذف العقوبات والسجل والجلسة. ويمكن لمسؤول الخادم أيضًا مسح سجل عضو بالأمر المخصّص.",
    "priv.droit3": "<strong>إيقاف كل معالجة</strong>: تكفي إزالة ModBot من الخادم. أما في لوحة التحكم، فزر «تسجيل الخروج» يمحو الجلسة من الطرفين.",
    "priv.secuTitre": "الأمان",
    "priv.secu1": "تمر الاتصالات مع البوت والموقع عبر HTTPS.",
    "priv.secu2": "تتطلب لوحة التحكم تسجيل دخول عبر ديسكورد؛ ويتحقق كل طلب من أنك تدير فعلًا الخادم المطلوب.",
    "priv.secu3": "تنتهي صلاحية الجلسات بعد سبعة أيام، وتُبطَل من جهة الخادم عند تسجيل الخروج.",
    "priv.secu4": "لا تُنشر ملفات البيانات أبدًا في مستودع الشيفرة العلني.",
    "priv.secuNote": "لا توجد خدمة معصومة. وإذا وقع تسريب يمس بياناتك، ستُنشر المعلومة في خادم الدعم.",
    "priv.mineursTitre": "السن الأدنى",
    "priv.mineursTexte": "يتبع ModBot شروط ديسكورد: تشترط المنصة سن 13 عامًا على الأقل، أو أكثر في بعض البلدان. والبوت غير موجّه إلى الأطفال دون هذه السن ولا يسعى لمعرفة عمر أحد.",
    "priv.majTitre": "التعديلات",
    "priv.majTexte": "تتبع هذه الصفحة الشيفرة. وأي تغيير في البوت يبدّل ما يُعالَج يؤدي إلى تحديثها، مع التاريخ في أعلى الصفحة. والسجل الكامل للتعديلات متاح للعموم في مستودع المشروع.",
    "priv.pied": "© 2026 ModBot — <a href=\"index.html\">الرئيسية</a> · <a href=\"conditions.html\">شروط الاستخدام</a>",

