    "cgu.tocFin": "التوقّف",
    "cgu.objetTitre": "الغرض",
    "cgu.objetTexte": "ModBot بوت ديسكورد للإشراف على المجتمعات وإدارتها، مع موقع ولوحة تحكم. تُقدَّم الخدمة كما هي، مجانًا، من فرد. وتنظّم هذه الشروط استخدامها.",
    "cgu.objetDiscord": "يمر استخدام ModBot عبر ديسكورد: تنطبق شروط ديسكورد وإرشادات مجتمعه إضافةً إلى هذه الشروط، وتَعلوها عند التعارض.",
    "cgu.accesTitre": "من يمكنه الاستخدام",
    "cgu.acces1": "يجب بلوغ السن الأدنى الذي يشترطه ديسكورد — 13 عامًا، وأكثر في بعض البلدان.",
    "cgu.acces2": "لا يستطيع إضافة ModBot وإعداده إلا من يملك صلاحية «إدارة الخادم».",
    "cgu.acces3": "مساحة الإدارة في الموقع مقصورة على الحسابات التي يأذن لها مالك البوت صراحةً.",
    "cgu.gratuitTitre": "المجانية والتبرعات",
    "cgu.gratuitTexte": "كل الميزات متاحة في كل الخوادم، دون حد زمني ودون مقابل. لا توجد باقة مدفوعة ولا ميزة محجوزة.",
    "cgu.gratuitDons": "التبرعات طوعية وتغطي تكاليف الاستضافة. <strong>التبرع لا يفتح أي شيء</strong>، ولا يمنح أي حق خاص، وغير قابل للاسترداد: فهو لا يشتري خدمة، بل يدعم مشروعًا.",
    "cgu.permTitre": "ما يطلبه ModBot",
    "cgu.permTexte": "عند التثبيت يعرض ديسكورد قائمة الصلاحيات المطلوبة. وهي تخدم الميزات التي تُفعّلها: حذف الرسائل للإشراف التلقائي، وإدارة الرتب للكابتشا ورتب التفاعل، وإنشاء القنوات للتذاكر، والحظر أو الطرد للعقوبات.",
    "cgu.permReduire": "يمكنك سحب أي صلاحية من إعدادات الخادم: ستتوقف الميزات المقابلة عن العمل فحسب، دون أن ينكسر الباقي. ولا يستخدم ModBot صلاحيةً لغير الميزة التي تبرّرها.",
    "cgu.adminTitre": "ما يقع على عاتق المسؤول",
    "cgu.adminTexte": "ينفّذ ModBot ما تمليه عليه الإعدادات. ويبقى المسؤول الذي ثبّته مسؤولًا عن خادمه وعمّا يختار تفعيله.",
    "cgu.admin1": "إبلاغ الأعضاء بأن الخادم يخضع لإشراف بوت، وبما يترتب على ذلك.",
    "cgu.admin2": "اختيار عقوبات متناسبة: فالحدود التلقائية تتصرف دون تدخل بشري.",
    "cgu.admin3": "التحقق من الصلاحيات الممنوحة، ولا سيما تسلسل الرتب.",
    "cgu.admin4": "الرد على طلبات أعضائه بشأن بياناتهم في خادمه.",
    "cgu.interditsTitre": "استخدامات محظورة",
    "cgu.interdit1": "استخدام ModBot للمضايقة أو التجسس أو الإضرار بأحد.",
    "cgu.interdit2": "تحويل الرسائل الخاصة أو الإعلانات إلى سبام أو دعاية غير مرغوبة.",
    "cgu.interdit3": "محاولة تجاوز الحمايات، أو إثقال الواجهة البرمجية، أو الوصول إلى بيانات خادم لا تديره.",
    "cgu.interdit4": "استخدام البوت في إطار غير قانوني، أو مخالف لقواعد ديسكورد.",
    "cgu.interdit5": "انتحال صفة مالك البوت أو فريق الدعم.",
    "cgu.dispoTitre": "التوافر",
    "cgu.dispoTexte": "يُقدَّم ModBot <strong>كما هو، دون أي ضمان</strong>. وقد تنقطع الخدمة لتحديث، أو لعطل في الاستضافة، أو لقيد من ديسكورد، أو قد تتوقف نهائيًا. لا يُوعد باستمرارية ولا يُستحق أي تعويض عن الانقطاع.",
    "cgu.dispoSauvegarde": "النسخ الاحتياطي للقنوات والرتب راحةٌ لا ضمان: احتفظ بنسخك الخاصة لما يهمّك.",
    "cgu.suspTitre": "التعليق",
    "cgu.suspTexte": "يجوز سحب الوصول إلى ModBot من حساب أو خادم في حال إساءة الاستخدام، ولا سيما الحالات المذكورة أعلاه. ويتخذ القرار مالك البوت، ويمكن مناقشته في خادم الدعم.",
    "cgu.respTitre": "المسؤولية",
    "cgu.respTexte": "في حدود ما يسمح به القانون، لا يمكن تحميل مالك ModBot مسؤولية نتائج عقوبة تلقائية، أو فقدان بيانات، أو انقطاع خدمة، ولا استخدام مسؤولٍ للبوت في خادمه.",
    "cgu.respRappel": "هذه الخدمة مجانية وتُصان في وقت شخصي. لا يعذر ذلك العيوب، لكنه يحدّد الإطار: لا يوجد عقد خدمة ولا التزام بمهلة.",
    "cgu.finTitre": "التوقف عن استخدام ModBot",
