    "roles.autoAfterCaptcha": "Auf die Verifizierung warten",
    "roles.autoAfterCaptchaHelp": "Empfohlen, solange das Captcha aktiv ist.",
    "roles.autoAfterCaptchaLong": "Ohne diese Option würde eine beim Beitritt vergebene Rolle den Zugang öffnen, bevor das Captcha bestanden ist — die Prüfung wäre wertlos. Bei deaktiviertem Captcha hat die Einstellung keine Wirkung.",
    "roles.autoEnable": "Rollen automatisch vergeben",
    "roles.autoEnableHelp": "Jedes neue Mitglied erhält sie ohne Zutun.",
    "roles.autoList": "Zu vergebende Rollen",
    "roles.autoListHelp": "Höchstens zehn Rollen. Eine Rolle, die in der Server-Hierarchie über ModBot steht, lässt sich nicht vergeben — Discord verweigert das. Das Protokoll nennt die übergangenen Rollen und den Grund.",
    "roles.autoTitle": "Beim Beitritt",
    "roles.eyebrow": "Vergabe",
    "roles.intro": "Zwei Wege, eine Rolle ohne Zutun zu vergeben. <strong>Beim Beitritt</strong>: die Rolle kommt von selbst, sobald jemand beitritt. <strong>Per Reaktion</strong>: das Mitglied wählt selbst, über ein Panel. Beides landet im Protokoll, Kategorie <strong>Rollen</strong>.",
    "roles.modeMulti": "Mehrere Rollen möglich",
    "roles.modeUnique": "Nur eine Rolle gleichzeitig",
