    "roles.reactionDescription": "Beschreibung",
    "roles.reactionHelp": "„Panel veröffentlichen“ speichert zuerst, sendet dann die Nachricht in den gewählten Kanal und setzt die Reaktionen. Ein erneutes Veröffentlichen erzeugt eine neue Nachricht: die alte vergibt dann keine Rollen mehr.",
