    "js.varPlateformeSociale": "Das Netzwerk: Twitch, TikTok…",
    "js.varTitrePublication": "Der Titel des Beitrags",
    "welcome.channelsHelp": "Beitritte und Austritte können in zwei verschiedene Kanäle gehen. Bleibt er leer, nutzt der Austrittskanal den Beitrittskanal — niemals umgekehrt.",
    "wiki.journalRoles": "Die Kategorie „Rollen“ hält auch fest, welche Rollen per Reaktion genommen oder zurückgegeben wurden, und welche automatischen Rollen beim Beitritt vergeben wurden — bei einem Fehlschlag mit dem Grund.",
    "wiki.journalSommaire": "Protokoll",
    "wiki.reseauxMessage": "Jeder Relais trägt seinen eigenen Ankündigungstext, etwa <code>{account} ist live, schaut vorbei!</code>. Er geht zusammen mit der Erwähnung in der Nachricht raus.",
    "wiki.reseauxSommaire": "Netzwerke",
    "wiki.reseauxVariables": "Vier Variablen: <code>{account}</code> das verfolgte Konto, <code>{platform}</code> das Netzwerk, <code>{title}</code> der Titel des Beitrags und <code>{link}</code> sein direkter Link.",
    "wiki.rolesAuto": "Beim Beitritt: bis zu zehn Rollen, vergeben sobald jemand dem Server beitritt.",
    "wiki.rolesBots": "Bots, die dem Server beitreten, erhalten nie eine automatische Rolle: sie kommen bereits mit den Rechten ihrer Einladung.",
    "wiki.rolesCaptcha": "Solange das Captcha aktiv ist, warten die automatischen Rollen, bis es bestanden wurde. Sonst öffnete die Rolle den Zugang vor der Prüfung, die damit wertlos wäre.",
    "wiki.rolesHierarchie": "Eine Rolle, die in der Hierarchie über ModBot steht, lässt sich nicht vergeben — Discord verweigert das. Das Protokoll nennt die übergangenen Rollen und den Grund.",
    "wiki.rolesMode": "Zwei Modi: mehrere Rollen gleichzeitig, oder nur eine — dann entfernt eine neue Rolle die vorherige.",
    "wiki.rolesModule": "Rollen: Rollen, die beim Beitritt automatisch vergeben werden, und ein Reaktionsrollen-Panel.",
    "wiki.rolesReaction": "Per Reaktion: ein Panel, das in einem Kanal veröffentlicht wird, eine Zeile je Rolle mit Emoji und Bezeichnung.",
    "wiki.rolesRepublier": "Ein erneutes Veröffentlichen erzeugt eine neue Nachricht. Die alte vergibt dann keine Rollen mehr und kann gelöscht werden.",
    "wiki.rolesSommaire": "Rollen",
    "wiki.rolesTexte": "Zwei Wege, eine Rolle ohne Zutun zu vergeben: beim Beitritt, oder vom Mitglied selbst über ein Panel gewählt. Beides landet im Protokoll, Kategorie „Rollen“.",
    "wiki.rolesTitre": "Automatische Rollen",
    "wiki.journalRolesCoupee": "Die Kategorie „Rollen“ ist standardmäßig aus: diese Ereignisse landen immer im Dashboard-Protokoll, aber für die Kopie in einen Discord-Kanal muss die Kategorie eingeschaltet werden.",
