    "js.faq.obtenir": "ModBot kann über Discord angefragt werden. Alle Funktionen sind kostenlos zugänglich: Sicherheit, Moderation, Kanäle und Logs, Tickets, Bewertungen und Anpassungen.",
    "js.faq.tarifs": "ModBot ist völlig kostenlos: Alle Funktionen stehen auf allen Servern zeitlich unbegrenzt bereit. Das Projekt lebt von freiwilligen Spenden, die nichts zusätzlich freischalten.",
    "js.faq.fonctionnalite": "Melde dich im ModBot-Discord. Beschreibe dein Anliegen, deinen Server und das erwartete Ergebnis: Erweiterungen werden anhand deiner Nutzung geprüft.",
    "js.faq.support": "Der Support läuft über den ModBot-Discord-Server. Du kannst eine Anfrage eröffnen und dein Problem oder Projekt schildern.",
    "js.faq.patch": "Die Patchnotes stehen im eigens dafür vorgesehenen Discord-Kanal. Wenn du schon auf dem Server bist, öffne den Patchnotes-Kanal. Andernfalls tritt zuerst dem ModBot-Server bei.",
